// newWatchCmd is the parent for the local price-watch workflow: add a
// product to a watchlist, re-check watched products' current prices, and
// see a digest of what changed since the last check.
func newWatchCmd(flags *rootFlags) *cobra.Command {
	cmd := &cobra.Command{
		Use:   "watch",
		Short: "Track Flipkart product prices locally and get notified when they drop to your threshold.",
		RunE:  parentNoSubcommandRunE(flags),
	}
	cmd.AddCommand(newWatchAddCmd(flags))
	cmd.AddCommand(newWatchCheckCmd(flags))
	cmd.AddCommand(newWatchDigestCmd(flags))
	return cmd
}
